// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    address constant DEPOSITOR = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

    function setUp() public { c = new L1Block(); }

    function testFuzz_property(bytes32 _hash) public {
        vm.startPrank(DEPOSITOR);

        c.setL1BlockValues(
            uint64(123),
            uint64(block.timestamp),
            uint256(0),
            _hash,
            uint64(1),
            bytes32(0),
            uint256(0),
            uint256(0)
        );

        vm.stopPrank();

        assertTrue(c.hash() == _hash);
    }
}
